        let exiled: GameEvent = json_as(json!({ "type": "exiled", "instanceId": old, "defId": watcher.id, "owner": "p2" }));
        state.applied.push(AppliedAction { nonce: format!("{seed}-exile"), events: vec![exiled] });
        let mut events: Vec<GameEvent> = Vec::new();
        restore(&mut state, &mut events, P1, 1, &[P1, P2]);
        state.applied.push(AppliedAction { nonce: seed.into(), events: events.clone() });
